;; curriculum: Precalc (gr 11) — trigonometry, y = a·sin(x−h)+k; prerequisites: valley, vector
;; math target: the terrain IS a sinusoid; amplitude a doubles wave height, phase h slides crests, midline k lifts the center.

app riya-level-sine "1.1.0"
"riya level 14 · The Sine Wave — a platformer + puzzle about reading y = A·sin(B·(x − H)) + K from its graph. Four multiple-choice gates set A, B, H, K; the wave redraws and reshapes the terrain instantly. The four ★ are placed at the crests and troughs of the target wave (A=2, B=1, H=0, K=2). A ★ only glows and can be collected when the current wave passes through its target point, so the student must solve the parameters first. Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-choice-gate + std-tutorial-overlay, rendered through math-canvas so the graph itself is the teacher."

;; @exposure internal

orbital RiyaSineOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Choice from "std/behaviors/std-choice-gate"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaSineBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaSineFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaSineFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }
  type RiyaSineStar = {
    id : string!
    x : number!
    y : number!
    targetY : number!
    active : boolean
    collected : boolean
  }
  type RiyaSineStarGate = {
    id : string!
    active : boolean!
  }
  type RiyaSineChoiceOption = {
    id : string!
    dx : number!
    label : string!
    correct : boolean!
    value : number!
  }
  type RiyaSineChoiceGate = {
    id : string!
    x : number!
    y : number!
    hint : string
    options : [RiyaSineChoiceOption]!
    solved : boolean
    chosen : string
  }
  type RiyaSinePlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaSineCurveSample = {
    x : number!
    y : number!
  }

  entity RiyaSineState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaSineBody = { x: -8, y: 2.5, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaSineFx] = []
    graphFx : [RiyaSineFx] = []
    celebrated : boolean = false
    ampA : number = 1
    periodB : number = 1
    phaseH : number = 0
    midK : number = 0
    choices : [RiyaSineChoiceGate] = []
    stars : [RiyaSineStar] = []
    pickupCompleted : boolean = false
    total : number = 0
    zoneId : string = "sine"
  }

  entity SineTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait SineBody = Body.traits.PlatformerBody -> RiyaSineState {
    events {
      STEER: SINE_STEER
      JUMP: SINE_LEAP
      PLACE: SINE_PLACE
      RESTART: SINE_RESTART
      CURVE_MOD_ADD: SINE_CURVE_MOD_ADD
      CURVE_MOD_CLEAR: SINE_CURVE_MOD_CLEAR
      BODY_JUMPED: SINE_JUMPED
      BODY_LANDED: SINE_LANDED
      BODY_HAZARD: SINE_HAZARD
      BODY_GOAL: SINE_GOAL
      BODY_FELL: SINE_FELL
      BODY_SKATE_START: SINE_SKATE_ON
      BODY_SKATE_END: SINE_SKATE_OFF
      SET_PLATFORMS: SINE_SET_PLATFORMS
      SET_SKATE_CURVE: SINE_SET_SKATE_CURVE
    }
    config {
      running: true
      spawn: { x: -8, y: 2.5, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 10
      killY: -3
      skate: true
      curveModsEnabled: true
      skateSnap: 0.9
    }
  }

  trait SineGate = Gate.traits.ObjectiveFlow -> RiyaSineState {
    events {
      PROGRESS: SINE_PROGRESS
      GAME_END: SINE_GAME_END
      RESTART: SINE_RESTART
    }
    config { running: true }
  }

  trait SineFx = Particles.traits.FxParticles -> RiyaSineState {
    events {
      BURST: SINE_BURST
    }
    config { running: true }
  }

  trait SinePickup = Pickup.traits.Pickup -> RiyaSineState {
    events {
      PICKED: SINE_PICKED
      COLLECT: SINE_COLLECT
      PICKUP_SET_COMPLETED: SINE_PICKUP_SET_COMPLETED
      SET_FEATURES: SINE_SET_FEATURES
      FEATURES_ACTIVE: SINE_FEATURES_ACTIVE
      RESTART: SINE_RESTART
    }
    fields {
      pickups: stars
    }
    config {
      running: true
      reachX: 0.7
      reachY: 0.7
    }
  }

  trait SineChoice = Choice.traits.ChoiceGate -> RiyaSineState {
    events {
      CHOICE_CORRECT: SINE_CHOICE_CORRECT
      CHOICE_WRONG: SINE_CHOICE_WRONG
      RESTART: SINE_RESTART
      SET_GATES: SINE_SET_GATES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait SineLevelData -> @rebindable RiyaSineState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "sine"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn s @s))
          gates: (array/map @config.gates (fn g @g))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaSinePlatform]!
        stars : [RiyaSineStar]!
        skateCurve : [RiyaSineCurveSample]
        gates : [RiyaSineChoiceGate]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/choice-gate authorities, and SineReward seeds its stars from it; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "The Sine Wave"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = 2·sin(x) + 2"
        @label "Equation"
        @description "The zone's target wave — the equation the four gates must be set to reproduce."
        @tier "presentation"
      concept : string = "Read y = A·sin(B·(x − H)) + K from its crests and troughs, then set the four gates to match."
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#f87171"
        @label "Region Color"
        @description "Zone band accent in the open world — the current-wave curve color."
        @tier "presentation"
      entryY : number = 2.544
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge — the skate curve's value at x = −10; the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 1.456
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge — the skate curve's value at x = 10; the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaSinePlatform] = [
        { id: "gate-amp-left", x: -7.4, y: 1.8, width: 0.8, height: 0.2, type: "platform" },
        { id: "gate-amp-mid", x: -6.0, y: 1.8, width: 0.8, height: 0.2, type: "platform" },
        { id: "gate-amp-right", x: -4.6, y: 1.8, width: 0.8, height: 0.2, type: "platform" },
