  trait SineChallenge -> @rebindable RiyaSineState [game-core, instance] {
    initial: idle

    state idle {
      RIYA_LEVEL_DATA -> idle when (and (== @entity.zoneId @config.zoneId) (== @payload.id "sine"))
        (set @entity.ampA 1)
        (set @entity.periodB 1)
        (set @entity.phaseH 0)
        (set @entity.midK 0)
        (set @entity.graphFx [])
        (emit SINE_CURVE_MOD_CLEAR {})
        (emit SINE_CURVE_MOD_ADD { x0: -10, x1: 10, a: 1, b: 1, h: 0, k: -2 })

      BODY_MOVED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (emit SINE_FEATURES_ACTIVE { updates: (array/map (array/filter @entity.stars (fn s (!= (object/get @s targetY null) null))) (fn s { id: (object/get @s id), active: (<= (math/abs (- (+ (* @entity.ampA (math/sin (* @entity.periodB (- (object/get @s x) @entity.phaseH)))) @entity.midK) (object/get @s targetY))) 0.3) })) })

      SINE_CHOICE_CORRECT -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (let ((gateState (array/find @entity.choices (fn g (== (object/get @g id) @payload.id)))))
        (let ((option (array/find (object/get @gateState options) (fn o (== (object/get @o id) (object/get @gateState chosen))))))
        (let ((val (object/get @option value)))
          (do
            (if (str/endsWith @payload.id "amp") (set @entity.ampA @val) (if (str/endsWith @payload.id "period") (set @entity.periodB @val) (if (str/endsWith @payload.id "phase") (set @entity.phaseH @val) (set @entity.midK @val))))
            (emit SINE_CURVE_MOD_CLEAR {})
            (emit SINE_CURVE_MOD_ADD { x0: -10, x1: 10, a: @entity.ampA, b: @entity.periodB, h: @entity.phaseH, k: (- @entity.midK (* 2 @entity.ampA)) })
            (emit SINE_BURST { particles: (array/map [ (object/get @gateState id) ] (fn _ { id: (str/concat "fx-choice-" @payload.id), type: "narrative", x: @payload.x, z: (+ @payload.y 1.5), y: 0, message: (if (str/endsWith @payload.id "amp") "2·sin(x)" (if (str/endsWith @payload.id "phase") "sin(x−h)" (if (str/endsWith @payload.id "mid") "+k" (object/get @option label)))), ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
          ))))

      SINE_CHOICE_WRONG -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (let ((gateState (array/find @entity.choices (fn g (== (object/get @g id) @payload.id)))))
        (let ((option (array/find (object/get @gateState options) (fn o (== (object/get @o id) @payload.optionId)))))
        (let ((val (object/get @option value)))
          (do
            (if (str/endsWith @payload.id "amp") (set @entity.ampA @val) (if (str/endsWith @payload.id "period") (set @entity.periodB @val) (if (str/endsWith @payload.id "phase") (set @entity.phaseH @val) (set @entity.midK @val))))
            (emit SINE_CURVE_MOD_CLEAR {})
            (emit SINE_CURVE_MOD_ADD { x0: -10, x1: 10, a: @entity.ampA, b: @entity.periodB, h: @entity.phaseH, k: (- @entity.midK (* 2 @entity.ampA)) })
            (emit SINE_BURST { particles: (array/map [ (object/get @gateState id) ] (fn _ { id: (str/concat "fx-choice-wrong-" @payload.id), type: "narrative", x: @payload.x, z: (+ @payload.y 1.5), y: 0, message: (object/get @gateState hint), ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f87171", size: 0.8, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
          ))))

      SINE_RESET -> idle when (== @entity.zoneId @config.zoneId)
        (emit SINE_RESTART { id: "board" })
        (set @entity.ampA 1)
        (set @entity.periodB 1)
        (set @entity.phaseH 0)
        (set @entity.midK 0)
        (set @entity.graphFx [])
        (emit SINE_CURVE_MOD_CLEAR {})
        (emit SINE_CURVE_MOD_ADD { x0: -10, x1: 10, a: 1, b: 1, h: 0, k: -2 })

      SINE_SKATE_ON -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (set @entity.graphFx [ { id: "graph-eq", type: "info", x: @payload.x, z: (+ @payload.y 1.5), y: 0, message: (str/concat "y = " (math/round @entity.ampA 1) "·sin(" (math/round @entity.periodB 1) "(x − " (math/round @entity.phaseH 2) ")) + " (math/round @entity.midK 1)), ttl: 60, maxTtl: 60, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.65, vx: 0, vy: 0, vz: 0, particleCount: 1 } ])
        (emit SINE_BURST { particles: (array/map [ "narrative-skate" "fx-sine-skate" ] (fn id
          (if (== @id "narrative-skate")
            { id: "narrative-skate", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 2), y: 0, message: "amplitude = height above midline", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
            { id: "fx-sine-skate", type: "info", x: @payload.x, z: (- @payload.y 0.3), message: (str/concat "slope = " (math/round @payload.slope 2)), ttl: 4, maxTtl: 4, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.5, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" }))) })

      SINE_SKATE_OFF -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (set @entity.graphFx [])
    }

    emits {
      SINE_CURVE_MOD_CLEAR -> external { }
        @description "Clear existing curve mods before applying a new parameter set."
        @tier "domain"
      SINE_CURVE_MOD_ADD -> external { x0 : number!, x1 : number!, a : number!, b : number, h : number!, k : number! }
        @description "Apply the combined sine parameter mod to the skate surface; with base wave sin(x)+2 the ground becomes exactly the live wave A·sin(B(x−H))+K."
        @tier "domain"
      SINE_FEATURES_ACTIVE -> external { updates : [RiyaSineStarGate]! }
        @description "Wave-alignment gates for the pickup authority: a star becomes collectible only when the live wave passes through it (|A·sin(B·(x−H)) + K − targetY| ≤ 0.3)."
        @tier "domain"
      SINE_RESTART -> external { id : string }
        @description "Reseed broadcast emitted on puzzle reset (KeyR); consumed by platformer-body, objective-flow, choice-gate, pickup, and fx-particles."
        @tier "domain"
      SINE_BURST -> external { particles : [RiyaSineFx] }
        @description "Particle batch for choices, skate readouts, and resets."
        @tier "domain"
    }

    listens {
      BODY_MOVED { x : number!, y : number!, vx : number!, vy : number!, grounded : boolean!, skating : boolean!, speed : number! }
      SINE_CHOICE_CORRECT { id : string!, x : number!, y : number! }
      SINE_CHOICE_WRONG { id : string!, optionId : string!, x : number!, y : number! }
      SINE_RESET { id : string }
      SINE_SKATE_ON { x : number!, y : number!, slope : number! }
      SINE_SKATE_OFF { x : number!, y : number! }
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaSinePlatform]!
        stars : [RiyaSineStar]!
        skateCurve : [RiyaSineCurveSample]
        gates : [RiyaSineChoiceGate]
      }
    }

    config {
      zoneId : string = "sine"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

