            keyUpMap: { ArrowLeft: "SINE_STOP", KeyA: "SINE_STOP", ArrowRight: "SINE_STOP", KeyD: "SINE_STOP" }
            curves: [
              { label: "", color: (if @entity.skating @config.curveSkateColor "#f87171"), samples: (array/map (array/range 0 80) (fn i { x: (+ -10 (* @i 0.25)), y: (+ (* @entity.ampA (math/sin (* @entity.periodB (- (+ -10 (* @i 0.25)) @entity.phaseH)))) @entity.midK) })) },
              { label: "", color: "#94a3b833", dash: "dashed", samples: (array/map (array/range 0 80) (fn i { x: (+ -10 (* @i 0.25)), y: (+ 2 (* 2 (math/sin (+ -10 (* @i 0.25))))) })) }
            ]
            bars: (array/map (array/range 0 9) (fn i { x: (+ -10 (* @i 2)), width: 2, y0: -2, y1: (+ (* @entity.ampA (math/sin (* @entity.periodB (- (+ -9 (* @i 2)) @entity.phaseH)))) @entity.midK), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.stars (fn s (== (object/get @s collected) false))) (fn s {
                x: (object/get @s x),
                y: (object/get @s y),
                label: (if (object/get @s active) "★" ""),
                color: (if (object/get @s active) @config.starColor "#64748b"),
                radius: (if (object/get @s active) 0.22 0.14),
                style: (if (object/get @s active) "open" "closed")
              }))
              (array/flatten (array/map @entity.choices (fn g (array/map (object/get @g options) (fn o {
                x: (+ (object/get @g x) (object/get @o dx)),
                y: (+ (object/get @g y) 0.6),
                label: (object/get @o label),
                color: "#a5b4fc",
                radius: 0.1,
                style: "closed"
              }))))))
            drawables: (array/concat
              (if (!= @config.playerSpriteUrl "") [ {
                type: "draw-sprite"
                position: { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3) }
                asset: { url: @config.playerSpriteUrl, atlas: @config.playerSpriteAtlas, role: "player", category: "sprite" }
                animation: (if @entity.body.grounded (if (!= @entity.body.vx 0) "skate" "idle") (if (> @entity.body.vy 0) "jump" "fall"))
                flipX: (not @entity.body.facingRight)
                width: @config.riyaSpriteWidth
                height: @config.riyaSpriteHeight
                anchor: "ground"
              } ] [])
              [ {
                type: "draw-fx-layer"
                items: (array/concat @entity.fx @entity.graphFx)
                tickMs: 500
                presets: @config.fxPresets
              } ])
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: "#facc15", label: "v" } ]
          } ]
        })
    }

    emits {
      SINE_LEFT -> external { id : string }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad."
        @tier "domain"
      SINE_RIGHT -> external { id : string }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad."
        @tier "domain"
      SINE_STOP -> external { id : string }
        @description "Left/right key release."
        @tier "domain"
      SINE_JUMP -> external { id : string }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up."
        @tier "domain"
      SINE_RESET -> external { id : string }
        @description "Reset the puzzle (KeyR): respawn riya and clear all choice gates."
        @tier "domain"
      SINE_STEER -> external { dir : number! }
        @description "Renamed STEER consumed by the platformer-body authority."
        @tier "domain"
      SINE_LEAP -> external { id : string }
        @description "Renamed JUMP consumed by the platformer-body authority."
        @tier "domain"
      SINE_PLACE -> external { x : number!, y : number! }
        @description "Renamed PLACE for pit-fall respawn."
        @tier "domain"
      SINE_FELL -> external { x : number!, y : number! }
        @description "Pit-fall signal from the platformer-body authority."
        @tier "domain"
      SINE_SKATE_ON -> external { x : number!, y : number!, slope : number! }
        @description "Skate-engage signal from the platformer-body authority; the challenge trait floats the live equation."
        @tier "domain"
      SINE_SKATE_OFF -> external { x : number!, y : number! }
        @description "Skate-release signal from the platformer-body authority; the challenge trait clears the floating equation."
        @tier "domain"
      SINE_PICKED -> external { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
        @description "A wave-gated star was collected (renamed PICKED from std-pickup); the play trait bursts ★."
        @tier "domain"
      SINE_COLLECT -> external { total : number! }
        @description "Running star count from the pickup authority (renamed COLLECT); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      SINE_PICKUP_SET_COMPLETED -> external { }
        @description "Every star collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      SINE_SET_FEATURES -> external { features : [RiyaSineStar]! }
        @description "Renamed SET_FEATURES consumed by the pickup authority; forwards the canonical RIYA_LEVEL_DATA stars."
        @tier "domain"
      SINE_RESTART -> external { id : string }
        @description "Reseed broadcast consumed by platformer-body, objective-flow, choice-gate, pickup, and fx-particles."
        @tier "domain"
      SINE_BURST -> external { particles : [RiyaSineFx] }
        @description "Particle batch for stars, falls, and tutorials."
        @tier "domain"
      SINE_PROGRESS -> external { objectivesLeft : number!, movesLeft : number! }
        @description "Progress signal consumed by the objective-flow gate."
        @tier "domain"
      SINE_GAME_END -> external { result : string! }
        @description "Win-gate resolution from the objective-flow authority."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external { level : string }
        @description "All ★ collected — the level is cleared."
        @tier "domain"
      SINE_SET_PLATFORMS -> external { platforms : [RiyaSinePlatform]! }
        @description "Renamed SET_PLATFORMS consumed by the platformer-body authority; forwards the canonical RIYA_LEVEL_DATA gate pads to collision."
        @tier "domain"
      SINE_SET_SKATE_CURVE -> external { curve : [RiyaSineCurveSample]! }
        @description "Renamed SET_SKATE_CURVE consumed by the platformer-body authority; forwards the canonical RIYA_LEVEL_DATA base wave as the skate surface."
        @tier "domain"
      SINE_SET_GATES -> external { gates : [RiyaSineChoiceGate]! }
        @description "Renamed SET_GATES consumed by the choice-gate authority; forwards the canonical RIYA_LEVEL_DATA A/B/H/K gates."
        @tier "domain"
    }

    listens {
      SINE_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
      SINE_COLLECT { total : number! }
      SINE_PICKUP_SET_COMPLETED { }
      SINE_TUTORIAL_DONE { id : string }
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaSinePlatform]!
        stars : [RiyaSineStar]!
        skateCurve : [RiyaSineCurveSample]
        gates : [RiyaSineChoiceGate]
      }
    }

    config {
      equationColor : string = "#7dd3fc"
        @label "Equation Color"
        @description "Color of the floating equation label that follows riya while she skates."
        @tier "presentation"
      curveSkateColor : string = "#f0abfc"
        @label "Curve Skate Color"
        @description "Curve trace color while riya is skating the graph."
        @tier "presentation"
      respawnX : number = -8
        @label "Respawn X"
        @description "X riya teleports to after a pit fall."
        @tier "domain"
      respawnY : number = 2.5
        @label "Respawn Y"
        @description "Y riya teleports to after a pit fall."
        @tier "domain"
      showTelemetry : boolean = false
        @label "Show Telemetry"
        @description "When true, draws a compact x/y/v readout on the canvas near riya."
        @tier "domain"
      arrowOffsetY : number = 2.3
        @label "Arrow Offset Y"
        @description "World units above the body center where the velocity vector arrow originates."
        @tier "presentation"
      arrowScale : number = 1.1
        @label "Arrow Scale"
        @description "Scale factor for the velocity vector arrow."
        @tier "presentation"
      playerSpriteUrl : string = "https://almadar-kflow-assets.web.app/shared/riya-platformer/units/riya/riya_sprite_sheet.png"
        @label "Player Sprite URL"
        @description "Riya sprite sheet; empty string falls back to the colored dot."
        @tier "presentation"
      playerSpriteAtlas : string = "https://almadar-kflow-assets.web.app/shared/riya-platformer/units/riya/atlas.json"
        @label "Player Sprite Atlas"
        @description "Sprite atlas JSON for riya's animations."
        @tier "presentation"
      riyaSpriteWidth : number = 1.0
        @label "Riya Sprite Width"
        @description "World-unit width of riya's sprite."
        @tier "presentation"
      riyaSpriteHeight : number = 1.0
        @label "Riya Sprite Height"
        @description "World-unit height of riya's sprite."
        @tier "presentation"
      fxPresets : [RiyaSineFxPreset] = [ { type: "info", color: "#38bdf8", color2: "#0c4a6e", size: 0.8, shape: "puff", count: 4 }, { type: "pickup", color: "#ffe066", color2: "#ffffff", size: 1.0, shape: "spark", count: 5, glow: 0.12, vy: -0.1 }, { type: "narrative", color: "#38bdf8", size: 1.4, shape: "ring", count: 1, glow: 0.1 } ]
        @label "Fx Presets"
        @description "Look table for world-space particle effects rendered by the draw-fx-layer."
        @tier "presentation"
      worldName : string = "The Sine Wave"
        @label "World Name"
        @description "Display name shown in the game-shell title chip."
        @tier "presentation"
      riyaColor : string = "#dc2626"
        @label "Riya Color"
        @description "Marker color for riya the dot."
        @tier "presentation"
      starColor : string = "#f59e0b"
        @label "Star Color"
