  }

  trait RiyaSineClear -> @rebindable RiyaSineState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "SINE_NEXT", variant: "primary" } ]
        })

      SINE_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      SINE_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-sine"
        @label "Next Path"
        @description "Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Sine clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "You read a sine graph: A = amplitude, B = frequency, H = phase, K = midline."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-sine" as RiyaSinePage -> SineLevelData, SineBody, SineGate, SineFx, SinePickup, SineChoice, SineTutorial, RiyaSineGenre, RiyaSinePlay, SineChallenge, RiyaSineClear
}
